import * as THREE from './vendor/three/three.module.js';
import {OrbitControls} from './vendor/three/OrbitControls.js';

// Geographic positions guide exploration, not navigation.
export const groundPositions={bernabeu:[40.453,-3.688],campnou:[41.381,2.123],anfield:[53.431,-2.961],allianz:[48.219,11.625],sansiro:[45.478,9.124],oldtrafford:[53.463,-2.291],dortmund:[51.493,7.452],paris:[48.841,2.253],emirates:[51.555,-.109],juventus:[45.110,7.641],etihad:[53.483,-2.200],tottenham:[51.604,-.067],stamfordbridge:[51.482,-.191],metropolitano:[40.436,-3.599],dragao:[41.162,-8.584],luz:[38.753,-9.185],galatasaray:[41.103,28.991],cruyff:[52.314,4.941],feyenoord:[51.894,4.523],celtic:[55.850,-4.206],bombonera:[-34.636,-58.365],monumental:[-34.545,-58.450],maracana:[-22.912,-43.230],napoli:[40.828,14.193]};
const vector=([lat,lon],radius=1)=>{const p=lat*Math.PI/180,t=lon*Math.PI/180;return new THREE.Vector3(Math.cos(p)*Math.cos(t),Math.sin(p),-Math.cos(p)*Math.sin(t)).multiplyScalar(radius);};
const safe=s=>String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const motion=()=>!matchMedia('(prefers-reduced-motion: reduce)').matches;

export class StadiumAtlas{
 constructor(host,{onOpen}={}){
  this.host=host;this.onOpen=onOpen;this.stadiums=[];this.buttons=[];this.active=true;this.visible=true;this.selected=null;
  host.innerHTML=`<div class="atlas-space"><div class="atlas-orbit orbit-one"></div><div class="atlas-orbit orbit-two"></div><div class="atlas-topline"><span><i></i> LIVE ATLAS / 主场星图</span><span id="atlas-coordinate">45° N / 10° E</span></div><div class="atlas-render" id="atlas-render"></div><svg class="atlas-leaders" id="atlas-leaders" aria-hidden="true"></svg><div class="atlas-labels" id="atlas-labels"></div><div class="atlas-vignette"></div><div class="atlas-heading"><p>THE WORLD IS<br>YOUR HOME GROUND.</p><span>世界很大。<br>找到让你心动的坐标。</span></div><div class="atlas-controls" role="group" aria-label="星图视角"><button data-atlas-region="europe" class="active">欧洲</button><button data-atlas-region="south">南美</button><button data-atlas-region="world">全球</button><button data-atlas-zoom="in" aria-label="放大主场星图">＋</button><button data-atlas-zoom="out" aria-label="缩小主场星图">−</button></div><div class="atlas-instructions"><span class="atlas-drag-icon">↔</span> 拖拽旋转地球 <i>·</i> 点亮坐标，飞入主场</div><div class="atlas-projection" aria-hidden="true">GROUND SIGNAL / <span id="atlas-signal">24</span> ACTIVE</div></div><aside class="atlas-directory"><div class="atlas-directory-heading"><span>选一个坐标</span><b id="atlas-list-count">24 GROUNDS</b></div><div class="atlas-preview"><span id="atlas-preview-country">YOUR NEXT DESTINATION</span><h3 id="atlas-preview-name">下一站，<br>由你点亮。</h3><p id="atlas-preview-club">掠过坐标，遇见一座主场。</p></div><div class="atlas-index" id="atlas-index" aria-label="星图球场索引"></div><p class="atlas-directory-note">不懂足球，也可以从一座城市开始。</p></aside>`;
  this.renderHost=host.querySelector('#atlas-render');this.labelHost=host.querySelector('#atlas-labels');this.leaderHost=host.querySelector('#atlas-leaders');
  host.addEventListener('click',e=>{const region=e.target.closest('[data-atlas-region]');if(region)this.region(region.dataset.atlasRegion);const zoom=e.target.closest('[data-atlas-zoom]');if(zoom)this.zoom(zoom.dataset.atlasZoom==='in'?.82:1.2);const cluster=e.target.closest('[data-atlas-cluster]');if(cluster)this.showCluster(cluster.dataset.atlasCluster,cluster);if(e.target.closest('[data-cluster-close]'))this.closeCluster();const jump=e.target.closest('[data-atlas-open]');if(jump){this.closeCluster();this.open(jump.dataset.atlasOpen);}});
  host.addEventListener('pointerover',e=>{const target=e.target.closest('[data-atlas-open]');if(target)this.preview(target.dataset.atlasOpen);});host.addEventListener('focusin',e=>{const target=e.target.closest('[data-atlas-open]');if(target){this.preview(target.dataset.atlasOpen);if(!this.restoring&&target.closest('.atlas-index'))this.focusGround(target.dataset.atlasOpen);}});
  try{this.init();}catch(error){host.classList.add('atlas-static');this.renderHost.innerHTML='<p class="atlas-offline">从右侧坐标索引，开启你的主场旅程。</p>';console.warn('Globe rendering unavailable:',error.message);}
  this.intersection=new IntersectionObserver(entries=>{this.visible=entries[0].isIntersecting;this.loop();},{rootMargin:'150px'});this.intersection.observe(host);
  this.onVisibility=()=>this.loop();document.addEventListener('visibilitychange',this.onVisibility);
 }
 init(){
  this.renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,powerPreference:'low-power'});this.renderer.setPixelRatio(Math.min(devicePixelRatio,2));this.renderer.setClearColor(0x000000,0);this.renderHost.append(this.renderer.domElement);this.renderer.domElement.tabIndex=0;this.renderer.domElement.setAttribute('role','img');this.renderer.domElement.setAttribute('aria-label','可旋转的主场地球，拖拽旋转，滚轮缩放；球场也可通过旁边的坐标索引选择');
  this.scene=new THREE.Scene();this.camera=new THREE.PerspectiveCamera(34,1,.1,100);this.camera.position.copy(vector([42,12],this.renderHost.clientWidth<600?4.9:3.6));
  this.scene.add(new THREE.AmbientLight('#c3ece6',1.3));const light=new THREE.DirectionalLight('#b2e0db',3.5);light.position.set(3,4,5);this.scene.add(light);const rim=new THREE.DirectionalLight('#347a9f',2);rim.position.set(-2,0,-3);this.scene.add(rim);
  this.earth=new THREE.Mesh(new THREE.SphereGeometry(1,96,64),new THREE.MeshStandardMaterial({color:'#24464b',roughness:.78,metalness:.15}));this.scene.add(this.earth);
  const atmosphere=new THREE.Mesh(new THREE.SphereGeometry(1.045,64,48),new THREE.ShaderMaterial({transparent:true,depthWrite:false,blending:THREE.AdditiveBlending,side:THREE.BackSide,uniforms:{glow:{value:new THREE.Color('#75ccbc')}},vertexShader:'varying vec3 n;varying vec3 v;void main(){vec4 p=modelViewMatrix*vec4(position,1.);n=normalize(normalMatrix*normal);v=normalize(-p.xyz);gl_Position=projectionMatrix*p;}',fragmentShader:'varying vec3 n;varying vec3 v;uniform vec3 glow;void main(){float a=pow(1.-abs(dot(n,v)),3.);gl_FragColor=vec4(glow,a*.32);}'}));this.scene.add(atmosphere);
  this.makeGrid();this.makeStars();
  this.controls=new OrbitControls(this.camera,this.renderer.domElement);this.controls.enableDamping=true;this.controls.dampingFactor=.07;this.controls.enablePan=false;this.controls.minDistance=1.65;this.controls.maxDistance=5.2;this.controls.rotateSpeed=.5;this.controls.zoomSpeed=.75;this.controls.autoRotate=false;this.controls.addEventListener('start',()=>{this.tween=null;this.closeCluster();this.host.classList.add('atlas-interacting');});this.controls.addEventListener('end',()=>this.host.classList.remove('atlas-interacting'));this.controls.addEventListener('change',()=>{this.updateLabels();if(document.hidden||!this.visible)this.draw();});
  this.renderer.domElement.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-','Home'].includes(e.key))return;e.preventDefault();if(['+','='].includes(e.key))return this.zoom(.85);if(e.key==='-')return this.zoom(1.18);if(e.key==='Home')return this.region('europe');const spherical=new THREE.Spherical().setFromVector3(this.camera.position);spherical.theta+=e.key==='ArrowLeft'?-.12:e.key==='ArrowRight'?.12:0;spherical.phi=THREE.MathUtils.clamp(spherical.phi+(e.key==='ArrowUp'?-.12:e.key==='ArrowDown'?.12:0),.1,3.04);this.moveTo(new THREE.Vector3().setFromSpherical(spherical));});
  this.resizeObserver=new ResizeObserver(()=>this.resize());this.resizeObserver.observe(this.renderHost);this.resize();
  fetch('./assets/earth-land.json').then(r=>{if(!r.ok)throw Error('map');return r.json();}).then(rings=>{const texture=this.earthTexture(rings);this.earth.material.map=texture;this.earth.material.color.set('#ffffff');this.earth.material.needsUpdate=true;this.host.dataset.mapReady='true';this.draw();}).catch(()=>{this.host.dataset.mapReady='outline';});
  this.host.dataset.atlasReady='true';this.loop();
 }
 earthTexture(rings){const c=document.createElement('canvas');c.width=2048;c.height=1024;const x=c.getContext('2d');x.fillStyle='#0b2029';x.fillRect(0,0,c.width,c.height);x.fillStyle='#31545a';x.strokeStyle='#63918b';x.lineWidth=.7;for(const ring of rings){x.beginPath();ring.forEach(([lon,lat],i)=>{const px=(lon+180)/360*c.width,py=(90-lat)/180*c.height;if(i===0)x.moveTo(px,py);else x.lineTo(px,py);});x.closePath();x.fill();x.stroke();}const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;t.anisotropy=8;return t;}
 makeGrid(){const lines=[],r=1.003;for(let lat=-60;lat<=60;lat+=30)for(let lon=-180;lon<180;lon+=3){const a=vector([lat,lon],r),b=vector([lat,lon+3],r);lines.push(...a.toArray(),...b.toArray());}for(let lon=-180;lon<180;lon+=30)for(let lat=-87;lat<87;lat+=3){const a=vector([lat,lon],r),b=vector([lat+3,lon],r);lines.push(...a.toArray(),...b.toArray());}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(lines,3));this.scene.add(new THREE.LineSegments(geo,new THREE.LineBasicMaterial({color:'#8cbbaf',transparent:true,opacity:.12})));}
 makeStars(){let seed=153;const rand=()=>{seed=seed*16807%2147483647;return(seed-1)/2147483646;},p=[];for(let i=0;i<450;i++){const v=new THREE.Vector3(rand()-.5,rand()-.5,rand()-.5).normalize().multiplyScalar(12+rand()*8);p.push(...v.toArray());}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(p,3));this.scene.add(new THREE.Points(g,new THREE.PointsMaterial({color:'#d3ece8',size:.014,sizeAttenuation:true,transparent:true,opacity:.5})));}
 setStadiums(stadiums,saved,seen){this.stadiums=stadiums;this.saved=saved;this.seen=seen;this.closeCluster();this.labelHost.replaceChildren();this.leaderHost.replaceChildren();const groups=new Map();stadiums.forEach(s=>{const members=groups.get(s.city)||[];members.push(s);groups.set(s.city,members);});this.groups=groups;
  this.buttons=[...groups].map(([city,members])=>{const s=members[0],button=document.createElement('button');button.className='atlas-pin';if(members.length===1)button.dataset.atlasOpen=s.id;else button.dataset.atlasCluster=city;button.style.setProperty('--pin-color',s.color);button.setAttribute('aria-label',members.length===1?'飞入'+s.name:city+'，展开'+members.length+'座球场');button.innerHTML=`<span class="pin-dot"></span><span class="pin-name">${safe(members.length===1?s.club.split(' / ')[0]:city+' · '+members.length)}</span>`;this.labelHost.append(button);const line=document.createElementNS('http://www.w3.org/2000/svg','line'),dot=document.createElementNS('http://www.w3.org/2000/svg','circle');line.setAttribute('stroke','#82b3a2');line.setAttribute('stroke-width','.7');line.setAttribute('opacity','.38');dot.setAttribute('fill',s.color);dot.setAttribute('r','2.6');this.leaderHost.append(line,dot);return{button,line,dot,s,members,position:vector(groundPositions[s.id],1.018)};});
  this.host.querySelector('#atlas-list-count').textContent=String(stadiums.length).padStart(2,'0')+' GROUNDS';this.host.querySelector('#atlas-signal').textContent=String(stadiums.length).padStart(2,'0');this.host.querySelector('#atlas-index').innerHTML=stadiums.map(s=>`<button class="atlas-index-item" data-atlas-open="${s.id}" aria-label="飞入${s.name}"><i style="--pin-color:${s.color}"></i><span>${safe(s.club.split(' / ')[0])}<small>${safe(s.city)}</small></span><b>${saved.has(s.id)?'♥':seen[s.id]?'✳':'↗'}</b></button>`).join('');
  if(stadiums.length)this.preview(stadiums.find(s=>s.id===this.selected)?.id||stadiums[0].id);if(stadiums.length&&stadiums.length<8&&!this.flightCamera)this.focusGround(stadiums[0].id);this.updateLabels();
 }
 showCluster(city,button){this.closeCluster();const members=this.groups.get(city);if(!members)return;const menu=document.createElement('div');menu.className='atlas-cluster-menu';menu.setAttribute('role','group');menu.setAttribute('aria-label',city+'的主场');menu.innerHTML=`<div><span>${safe(city)} / ${members.length} GROUNDS</span><button data-cluster-close aria-label="关闭城市球场选择">×</button></div>`+members.map(s=>`<button data-atlas-open="${s.id}"><i style="background:${s.color}"></i><span>${safe(s.club)}<small>${safe(s.name)}</small></span><b>↗</b></button>`).join('');const r=button.getBoundingClientRect(),space=this.labelHost.getBoundingClientRect();menu.style.left=Math.max(14,Math.min(space.width-230,r.x-space.x))+'px';menu.style.top=Math.max(55,Math.min(space.height-menu.childElementCount*61-40,r.y-space.y+35))+'px';this.labelHost.append(menu);this.clusterMenu=menu;}
 closeCluster(){this.clusterMenu?.remove();this.clusterMenu=null;}
 preview(id){const s=this.stadiums.find(s=>s.id===id);if(!s)return;this.selected=id;this.host.querySelector('#atlas-preview-country').textContent=s.country+' / '+s.city;this.host.querySelector('#atlas-preview-name').textContent=s.name;this.host.querySelector('#atlas-preview-club').textContent=s.club;this.host.style.setProperty('--selected-club',s.color);this.buttons.forEach(p=>p.button.classList.toggle('is-selected',p.members.some(s=>s.id===id)));}
 open(id){this.preview(id);this.onOpen?.(id);}
 focusGround(id){if(!this.camera)return;this.moveTo(vector(groundPositions[id],this.renderHost.clientWidth<600?2.9:2.7));}
 region(region){this.closeCluster();this.host.querySelectorAll('[data-atlas-region]').forEach(b=>b.classList.toggle('active',b.dataset.atlasRegion===region));this.moveTo(vector(region==='south'?[-25,-55]:[42,12],region==='world'?4.8:this.renderHost.clientWidth<600?4.9:3.6));}
 zoom(scale){this.closeCluster();if(!this.camera)return;this.moveTo(this.camera.position.clone().setLength(THREE.MathUtils.clamp(this.camera.position.length()*scale,1.65,5.2)));}
 moveTo(target){if(!this.camera)return;if(!motion()||document.hidden){this.camera.position.copy(target);this.controls.update();this.updateLabels();this.draw();return;}this.tween={from:this.camera.position.clone(),to:target,start:performance.now()};this.loop();}
 resize(){if(!this.renderer)return;const w=this.renderHost.clientWidth,h=this.renderHost.clientHeight;if(!w||!h)return;this.renderer.setSize(w,h);this.camera.aspect=w/h;this.camera.updateProjectionMatrix();this.updateLabels();this.draw();}
 updateLabels(){if(!this.camera)return;const w=this.renderHost.clientWidth,h=this.renderHost.clientHeight;this.leaderHost.setAttribute('viewBox',`0 0 ${w} ${h}`);const direction=this.camera.position.clone().normalize();const candidates=this.buttons.map(p=>{const v=p.position.clone().project(this.camera);return{...p,x:(v.x*.5+.5)*w,y:(-.5*v.y+.5)*h,front:p.position.clone().normalize().dot(direction)>.2};});const visible=candidates.filter(p=>p.front&&p.x>10&&p.x<w-10&&p.y>20&&p.y<h-20).sort((a,b)=>a.y-b.y);for(const p of candidates){const show=visible.includes(p);p.button.hidden=!show;p.line.style.display=p.dot.style.display=show?'':'none';}const columns=[visible.filter((_,i)=>i%2===0),visible.filter((_,i)=>i%2===1)];columns.forEach((items,side)=>{const gap=w<500?33:35,start=Math.max(143,(h-items.length*gap)/2);items.forEach((p,i)=>{const x=side?Math.min(w-125,w*.73):Math.max(18,w*.19-40),y=start+i*gap;p.button.style.transform=`translate(${x}px,${y}px)`;p.line.setAttribute('x1',p.x);p.line.setAttribute('y1',p.y);p.line.setAttribute('x2',x+(side?0:85));p.line.setAttribute('y2',y+14);p.dot.setAttribute('cx',p.x);p.dot.setAttribute('cy',p.y);});});const v=this.camera.position,lat=Math.asin(v.y/v.length())*180/Math.PI,lon=-Math.atan2(v.z,v.x)*180/Math.PI;this.host.querySelector('#atlas-coordinate').textContent=Math.abs(lat).toFixed(0)+'° '+(lat>=0?'N':'S')+' / '+Math.abs(lon).toFixed(0)+'° '+(lon>=0?'E':'W');this.host.dataset.camera=v.toArray().map(x=>x.toFixed(3)).join(',');}
 fly(id){this.flightCamera??=this.camera.position.clone();this.moveTo(vector(groundPositions[id],1.75));clearTimeout(this.flightTimer);this.flightTimer=setTimeout(()=>this.pause(),600);}
 draw(){if(this.renderer&&this.scene&&this.camera)this.renderer.render(this.scene,this.camera);}
 pause(){clearTimeout(this.flightTimer);this.active=false;this.renderer?.setAnimationLoop(null);}
 resume(){clearTimeout(this.flightTimer);if(this.flightCamera){this.camera.position.copy(this.flightCamera);this.flightCamera=null;this.tween=null;this.controls.update();this.updateLabels();}this.active=true;this.loop();}
 loop(){if(!this.renderer)return;if(!this.active||!this.visible||document.hidden){this.renderer.setAnimationLoop(null);return;}this.renderer.setAnimationLoop(()=>{if(this.tween){const t=Math.min(1,(performance.now()-this.tween.start)/950),k=1-(1-t)**3;const from=this.tween.from.clone().normalize(),to=this.tween.to.clone().normalize(),q=new THREE.Quaternion().setFromUnitVectors(from,to),partial=new THREE.Quaternion().slerp(q,k);this.camera.position.copy(from.applyQuaternion(partial)).multiplyScalar(THREE.MathUtils.lerp(this.tween.from.length(),this.tween.to.length(),k));if(t===1)this.tween=null;}this.controls.update();this.renderer.render(this.scene,this.camera);this.updateLabels();});}
 dispose(){this.pause();this.intersection.disconnect();this.resizeObserver?.disconnect();this.controls?.dispose();this.scene?.traverse(o=>{o.geometry?.dispose();o.material?.map?.dispose();o.material?.dispose();});this.renderer?.dispose();document.removeEventListener('visibilitychange',this.onVisibility);}
}
